"use strict";

/*
 * PyDebug Local AI — an on-server problem generator that needs no AI API key
 * and makes zero network calls.
 *
 * Guarantees the generator is built around:
 *   1. Every "bug" problem's starter code REALLY raises the advertised Python
 *      exception (ValueError, IndexError, TypeError, KeyError, ...) when run.
 *   2. Every "question" problem's code runs cleanly and `expected_output` is
 *      the program's real stdout, mirrored with exact Python 3 semantics.
 *   3. Generation is seeded, so a preview can be re-generated byte-for-byte at
 *      publish time, and normalized titles/code are de-duplicated against the
 *      existing library so the same problem is never added twice.
 *
 * Templates are deterministic given (seed, count, filters). All arithmetic is
 * restricted to ranges where JavaScript numbers are exact integers (< 2^53)
 * and float formatting matches Python's repr (shortest round-trip form).
 * `scripts/verify-ai-engine.js` cross-checks every template against a real
 * CPython interpreter and `tests/ai-engine.test.js` re-runs a smaller version
 * of that check in CI when python3 is available.
 */

const crypto = require("node:crypto");

