/* ------------------------------------------------------------------ *
 * Seeded RNG (mulberry32) — deterministic per seed.
 * ------------------------------------------------------------------ */
function mulberry32(seed) {
  let a = seed >>> 0;
  return function next() {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function createRng(seed) {
  const next = mulberry32(seed);
  return {
    int: (min, max) => min + Math.floor(next() * (max - min + 1)),
    pick: (list) => list[Math.floor(next() * list.length)],
    bool: () => next() < 0.5,
    shuffle: (list) => {
      const out = [...list];
      for (let i = out.length - 1; i > 0; i -= 1) {
        const j = Math.floor(next() * (i + 1));
        [out[i], out[j]] = [out[j], out[i]];
      }
      return out;
    },
  };
}

function uniqueInts(rng, count, min, max) {
  const seen = new Set();
  while (seen.size < count) seen.add(rng.int(min, max));
  return [...seen];
}

/* ------------------------------------------------------------------ *
 * Python semantics helpers (the "mirror" that computes real output).
 * ------------------------------------------------------------------ */

// Python 3 prints integral floats as "84.0"; both languages otherwise emit the
// shortest round-trip decimal for doubles, which agrees for our value ranges.
function pyFloatStr(value) {
  if (!Number.isFinite(value)) throw new Error("generator produced a non-finite float");
  if (Number.isInteger(value) && Math.abs(value) < 1e15) return `${value}.0`;
  return String(value);
}

function pyList(items) { return `[${items.join(", ")}]`; }
function pyStrList(items) { return `[${items.map((item) => `'${item}'`).join(", ")}]`; }
function pyTitle(word) { return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase(); }
function factorial(n) { let out = 1; for (let i = 2; i <= n; i += 1) out *= i; return out; }

