const TEMPLATES = Object.freeze([...BUG_TEMPLATES, ...OUTPUT_TEMPLATES]);

/* ------------------------------------------------------------------ *
 * Premium mix — deterministic per seed so preview and publish agree.
 * ------------------------------------------------------------------ */
const PREMIUM_MODES = Object.freeze({
  none: 0,
  quarter: 0.25,
  third: 1 / 3,
  half: 0.5,
});

function parsePremiumMode(value) {
  return Object.prototype.hasOwnProperty.call(PREMIUM_MODES, value) ? value : "none";
}

function premiumCountFor(total, mode) {
  if (mode === "none" || total < 1) return 0;
  // "quarter" of 10 -> 3 (2.5 rounds up), "third" of 10 -> 3, "half" of 10 -> 5.
  return Math.min(total, Math.max(1, Math.round(total * PREMIUM_MODES[mode])));
}

function applyPremium(problems, mode, seed) {
  const count = premiumCountFor(problems.length, parsePremiumMode(mode));
  if (!count) return problems.map((problem) => ({ ...problem, is_premium: false }));
  // A dedicated RNG stream (seed XOR a fixed salt) keeps premium selection
  // independent from content generation.
  const rng = createRng(((Number(seed) >>> 0) ^ 0x5f3759df) >>> 0);
  const chosen = new Set(rng.shuffle(problems.map((_, index) => index)).slice(0, count));
  return problems.map((problem, index) => ({ ...problem, is_premium: chosen.has(index) }));
}

/* ------------------------------------------------------------------ *
 * Filters, generation and de-duplication.
 * ------------------------------------------------------------------ */
function parseFilters({ type, difficulty } = {}) {
  const resolvedType = ["any", "bug", "question"].includes(type) ? type : "any";
  const resolvedDifficulty = ["any", "easy", "medium", "hard"].includes(difficulty) ? difficulty : "any";
  const eligible = TEMPLATES.filter((template) =>
    (resolvedType === "any" || template.type === resolvedType)
    && (resolvedDifficulty === "any" || template.difficulty === resolvedDifficulty));
  if (!eligible.length) {
    const error = new Error("No generator templates match that type and difficulty combination");
    error.status = 400;
    error.code = "no_templates";
    throw error;
  }
  return { type: resolvedType, difficulty: resolvedDifficulty };
}

function normalizeTitle(title) {
  return String(title || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
}

function normalizeCode(code) {
  return String(code || "").toLowerCase().replace(/\s+/g, "");
}

function problemKeys(problem) {
  return [`t:${normalizeTitle(problem.title)}`, `c:${normalizeCode(problem.starter_code)}`];
}

function keysForRow(row) {
  const keys = [];
  if (row && row.title) keys.push(`t:${normalizeTitle(row.title)}`);
  if (row && row.starter_code) keys.push(`c:${normalizeCode(row.starter_code)}`);
  return keys;
}

function generateProblems({ seed, count, type = "any", difficulty = "any", premium = "none" }) {
  const filters = parseFilters({ type, difficulty });
  const pool = TEMPLATES.filter((template) =>
    (filters.type === "any" || template.type === filters.type)
    && (filters.difficulty === "any" || template.difficulty === filters.difficulty));
  const rng = createRng(Number.isInteger(seed) ? seed >>> 0 : 1);
  const wanted = Math.max(1, Math.min(MAX_BATCH, Math.floor(Number(count) || 1)));
  let queue = rng.shuffle(pool);
  let queueIndex = 0;
  const problems = [];
  const seen = new Set();
  let attempts = 0;
  while (problems.length < wanted && attempts < GENERATION_ATTEMPTS) {
    attempts += 1;
    if (queueIndex >= queue.length) { queue = rng.shuffle(pool); queueIndex = 0; }
    const template = queue[queueIndex];
    queueIndex += 1;
    const problem = template.make(rng);
    const keys = problemKeys(problem);
    if (keys.some((key) => seen.has(key))) continue;
    keys.forEach((key) => seen.add(key));
    problems.push({
      ...problem,
      type: template.type,
      difficulty: template.difficulty,
      topic: template.topic,
      template: template.key,
    });
  }
  return applyPremium(problems, premium, seed);
}

function batchSignature(problems) {
  return crypto.createHash("sha256").update(JSON.stringify(problems)).digest("hex").slice(0, 32);
}

function generateFromTemplate(key, seed) {
  const template = TEMPLATES.find((candidate) => candidate.key === key);
  if (!template) {
    const error = new Error(`Unknown template: ${key}`);
    error.status = 400;
    throw error;
  }
  const made = template.make(createRng(Number.isInteger(seed) ? seed >>> 0 : 1));
  return {
    ...made,
    type: template.type,
    difficulty: template.difficulty,
    topic: template.topic,
    template: template.key,
  };
}

function engineLabel() {
  return `${ENGINE_ID}/v${ENGINE_VERSION}`;
}

function templateInventory() {
  const inventory = { bug: {}, question: {} };
  for (const template of TEMPLATES) {
    inventory[template.type][template.difficulty] = (inventory[template.type][template.difficulty] || 0) + 1;
  }
  return inventory;
}

module.exports = {
  ENGINE_ID,
  ENGINE_VERSION,
  MAX_BATCH,
  TEMPLATES,
  engineLabel,
  parseFilters,
  generateProblems,
  parsePremiumMode,
  premiumCountFor,
  applyPremium,
  batchSignature,
  problemKeys,
  keysForRow,
  normalizeTitle,
  normalizeCode,
  templateInventory,
  _internals: { createRng, pyFloatStr, pyList, pyStrList, pyTitle, generateFromTemplate },
};
